/* the mask's own rasterisation; the record's size decides the drawn size. */
#define SW_LABEL_WIDTH 81u
#define SW_LABEL_HEIGHT 16u

/* Sightings needed before a caption id is trusted as SPIRAL's. */
#define SW_LABEL_CONFIRM 2u

static const unsigned char sw_label_owner;
static unsigned int sw_label_last;
static unsigned int sw_label_streak;
static unsigned int sw_label_painted;

/* Is SPIRAL the effect the play screen is showing? */
static int swang_label_shown(void)
{
    void *manager = framework->beatfx->manager ? framework->beatfx->manager() : 0;
    return manager && rx3_beatfx_on(manager, BEAT_FX_SPIRAL);
}

/* render thread. Two sightings in a row, and only while SPIRAL is the shown
   effect; anything else clears the count so the grid cannot vote. */
static void swang_label_drawn(unsigned int image)
{
    if (image < SW_CAPTION_FIRST || image > SW_CAPTION_LAST || !swang_label_shown()) {
        sw_label_last = 0u;
        sw_label_streak = 0u;
        return;
    }
    if (image == sw_label_last)
        sw_label_streak++;
    else {
        sw_label_last = image;
        sw_label_streak = 1u;
    }
    if (sw_label_streak < SW_LABEL_CONFIRM || sw_label_painted == image) return;
    if (!framework->images->paint_masked_now) {
        sw_label_painted = image;
        framework->log_line("swang: the caption cannot be painted");
        return;
    }
    if (framework->images->paint_masked_now(&sw_label_owner, image,
                                            SW_LABEL_WIDTH, SW_LABEL_HEIGHT,
                                            sw_label_caption_coverage)) {
        sw_label_painted = image;
        framework->log_number("swang: caption relabelled = ", image);
    }
}

static void swang_labels_install(void)
{
    if (!framework->images || !framework->images->claim_drawn) {
        framework->log_line("swang: the caption stays stock");
        return;
    }
    if (!framework->images->claim_drawn(&sw_label_owner, swang_label_drawn))
        framework->log_line("swang: no room to watch the caption");
}

static void swang_labels_release(void)
{
    if (framework->images && framework->images->unregister_owner)
        framework->images->unregister_owner(&sw_label_owner);
}

#endif /* RX3_SWANG_LABELS_H */
